def _payment_service_date(job):
    """Business date used for chasing: completion date when available, otherwise route date."""
    raw = clean_val(job.get("CompletedTime")) or clean_val(job.get("completed_time"))
    if raw:
        try:
            dt = pd.to_datetime(raw, errors="raise")
            if getattr(dt, "tzinfo", None) is not None:
                dt = dt.tz_convert("Europe/London")
            return dt.date()
        except Exception:
            pass
    try:
        return pd.to_datetime(clean_val(job.get("_route_date"))).date()
    except Exception:
        return None


def _payment_reminder_stage(job, today=None):
    """Return 3, 7, 14, or 0. Day 14 is attention-only and never auto-queued."""
    today = today or datetime.now(ZoneInfo("Europe/London")).date()
    service_day = _payment_service_date(job)
    if service_day is None:
        return 0
    age = (today - service_day).days
    if age < 3:
        return 0
    if age >= 14:
        return 14
    # Age decides which reminder is due. A job already 7+ days old must not
    # fall back to a Day 3 reminder just because Day 3 was never sent.
    if age >= 7:
        return 0 if clean_val(job.get("PaymentReminderDay7SentAt")) else 7
    return 0 if clean_val(job.get("PaymentReminderDay3SentAt")) else 3


def _payment_customer_key(job):
    """Stable customer key used only to prevent duplicate SMS reminders in one batch."""
    address = clean_val(job.get("Address")) or clean_val(job.get("address_text"))
    postcode = normalise_postcode(job.get("Postcode"))
    phone = normalise_phone(job.get("Phone"))
    return (address.strip().lower(), postcode.strip().upper(), phone.strip())


def _dedupe_payment_reminders(jobs):
    """One SMS per customer: keep the oldest/highest-stage outstanding clean."""
    chosen = {}
    for job in jobs:
        key = _payment_customer_key(job)
        current = chosen.get(key)
        score = (int(job.get("_reminder_stage", 0) or 0), int(job.get("_age_days", 0) or 0))
        current_score = (-1, -1) if current is None else (
            int(current.get("_reminder_stage", 0) or 0), int(current.get("_age_days", 0) or 0)
        )
        if current is None or score > current_score:
            chosen[key] = job
    return list(chosen.values())


def _payment_reminder_message(job, stage):
    amount = float(job.get("Price", 0) or 0)
    service_day = _payment_service_date(job)
    service_text = service_day.strftime("%d/%m/%Y") if service_day else clean_val(job.get("_route_date"))
    if int(stage) == 7:
        return (
            f"Hi, this is DanCleanUK. Just a second reminder that the £{amount:.2f} payment "
            f"for your window clean on {service_text} is still showing as outstanding. "
            "If you've already paid, please ignore this message. Otherwise, we'd appreciate "
            "it if you could arrange payment when possible. Thank you, DanCleanUK."
        )
    return (
        f"Hi, this is DanCleanUK 👋 Just a friendly reminder that the £{amount:.2f} payment "
        f"for your window clean on {service_text} is still showing as outstanding. "
        "If you've already made the payment, please ignore this message. Thank you! DanCleanUK"
    )


def _payment_reminder_sms_url(job, stage):
    number = normalise_phone(job.get("Phone"))
    if number and not number.startswith("+"):
        number = "+" + number
    return "sms:" + quote(number, safe="+") + "?body=" + quote(_payment_reminder_message(job, stage))


def _admin_patch_saved_route_job(route_date, job_id, updates):
    """Patch only one job's business metadata inside an existing permanent route."""
    snapshot = load_route_snapshot(route_date)
    if not snapshot:
        return False
    route_data = dict(snapshot.get("route_data") or {})
    jobs_data = [dict(x) for x in (route_data.get("jobs_data") or [])]
    changed = False
    for job in jobs_data:
        if str(job.get("job_id")) == str(job_id):
            job.update(dict(updates or {}))
            changed = True
            break
    if not changed:
        return False
    route_data["jobs_data"] = jobs_data
    url, _ = _supabase_config()
    headers = _supabase_headers("return=representation")
    if not url or not headers:
        return False
    try:
        response = requests.patch(
            f"{url}/rest/v1/saved_routes",
            headers=headers,
            params={"route_date": f"eq.{route_date}", "select": "route_date"},
            json={"route_data": route_data, "updated_at": datetime.now(timezone.utc).isoformat()},
            timeout=30,
        )
        return response.status_code == 200 and bool(response.json())
    except (requests.RequestException, ValueError, TypeError):
        return False


def _admin_prepare_payment_reminder_queue(selected):
    """Replace the payment-reminder queue with exactly the selected route jobs."""
    routes = _admin_load_saved_routes()
    selected_keys = {
        (str(x.get("_route_date")), str(x.get("job_id"))): int(x.get("_reminder_stage", 0))
        for x in selected
    }
    url, _ = _supabase_config()
    headers = _supabase_headers("return=representation")
    if not url or not headers:
        return False, "Supabase is not available."

    try:
        changed_routes = 0
        queued_count = 0
        for snapshot in routes:
            route_date = clean_val(snapshot.get("route_date"))
            route_data = dict(snapshot.get("route_data") or {})
            jobs_data = [dict(x) for x in (route_data.get("jobs_data") or [])]
            route_changed = False
            for job in jobs_data:
                key = (str(route_date), str(job.get("job_id")))
                wanted_stage = selected_keys.get(key, 0)
                old_stage = int(job.get("PaymentReminderQueuedStage", 0) or 0)
                if old_stage != wanted_stage:
                    job["PaymentReminderQueuedStage"] = wanted_stage
                    job["PaymentReminderQueuedAt"] = (
                        datetime.now(timezone.utc).isoformat() if wanted_stage else ""
                    )
                    route_changed = True
                if wanted_stage:
                    queued_count += 1
            if route_changed:
                route_data["jobs_data"] = jobs_data
                response = requests.patch(
                    f"{url}/rest/v1/saved_routes",
                    headers=headers,
                    params={"route_date": f"eq.{route_date}", "select": "route_date"},
                    json={"route_data": route_data, "updated_at": datetime.now(timezone.utc).isoformat()},
                    timeout=30,
                )
                if response.status_code != 200:
                    return False, "Could not save the complete payment reminder queue."
                changed_routes += 1
        return True, queued_count
    except (requests.RequestException, ValueError, TypeError):
        return False, "Could not save the payment reminder queue. Please try again."


def _admin_load_payment_reminder_queue():
    queued = []
    for job in _admin_jobs_from_routes(_admin_load_saved_routes()):
        stage = int(job.get("PaymentReminderQueuedStage", 0) or 0)
        if stage not in (3, 7):
            continue
        status = clean_val(job.get("Status")).lower()
        payment = clean_val(job.get("Payment"))
        if status != "completed" or payment not in {"Bank Transfer", "Not Paid"}:
            continue
        item = dict(job)
        item["_reminder_stage"] = stage
        queued.append(item)
    return sorted(queued, key=lambda x: (x.get("_route_date", ""), clean_val(x.get("address_text"))))


def _admin_mark_payment_reminder_sent(job):
    stage = int(job.get("_reminder_stage", 0) or 0)
    field = "PaymentReminderDay7SentAt" if stage == 7 else "PaymentReminderDay3SentAt"
    return _admin_patch_saved_route_job(
        job.get("_route_date"),
        job.get("job_id"),
        {
            field: datetime.now(timezone.utc).isoformat(),
            "PaymentReminderQueuedStage": 0,
            "PaymentReminderQueuedAt": "",
        },
    )


def _payment_phone_reset_session():
    for key in (
        "payment_reminder_active_queue",
        "payment_reminder_index",
        "payment_reminder_sent_count",
    ):
        st.session_state.pop(key, None)


# ============================================================
# ADMIN PAYMENT REMINDER PHONE MODE
# ============================================================
if PAYMENT_REMINDER_MODE:
    st.title("💷 DanCleanUK — Payment Reminders")
    st.caption("Send prepared payment reminders through this phone's normal Messages app")

    active_queue = st.session_state.get("payment_reminder_active_queue")
    if not active_queue:
        queued = _admin_load_payment_reminder_queue()
        if not queued:
            st.success("No payment reminders are prepared for this phone.")
            st.caption("Prepare selected reminders from Admin → Outstanding Payments first.")
            if st.button("🔄 Refresh", use_container_width=True):
                st.rerun()
            st.stop()

        st.success(f"{len(queued)} payment reminder(s) ready.")
        for row in queued:
            address = clean_val(row.get("Address")) or clean_val(row.get("address_text")) or "Customer"
            stage = int(row.get("_reminder_stage", 3))
            with st.container(border=True):
                st.markdown(f"**{address}**")
                st.caption(
                    f"{normalise_postcode(row.get('Postcode'))} · £{float(row.get('Price', 0) or 0):.2f} "
                    f"· Day {stage} reminder"
                )

        if st.button(
            f"▶️ START SENDING {len(queued)} PAYMENT REMINDER(S)",
            type="primary",
            use_container_width=True,
            key="payment_reminder_start",
        ):
            st.session_state["payment_reminder_active_queue"] = queued
            st.session_state["payment_reminder_index"] = 0
            st.session_state["payment_reminder_sent_count"] = 0
            st.rerun()
        st.stop()

    queue = st.session_state.get("payment_reminder_active_queue", [])
    index = int(st.session_state.get("payment_reminder_index", 0))
    sent_count = int(st.session_state.get("payment_reminder_sent_count", 0))

    if index >= len(queue):
        st.success(f"✅ Payment reminder session finished. {sent_count} marked as sent.")
        remaining = _admin_load_payment_reminder_queue()
        if remaining:
            st.info(f"{len(remaining)} reminder(s) remain prepared — for example customers you skipped.")
        else:
            st.info("No prepared payment reminders remain.")
        if st.button("🔄 RELOAD REMAINING QUEUE", type="primary", use_container_width=True):
            _payment_phone_reset_session()
            st.rerun()
        st.stop()

    current = queue[index]
    stage = int(current.get("_reminder_stage", 3))
    address = clean_val(current.get("Address")) or clean_val(current.get("address_text")) or "Customer"
    st.progress((index + 1) / max(1, len(queue)))
    st.caption(f"Customer {index + 1} of {len(queue)} · {sent_count} marked sent")
    st.markdown(f"### {address}")
    st.write(normalise_postcode(current.get("Postcode")))
    st.write(f"📞 {clean_val(current.get('Phone'))}")
    st.write(f"**£{float(current.get('Price', 0) or 0):.2f} outstanding · Day {stage} reminder**")

    with st.expander("Message", expanded=True):
        st.write(_payment_reminder_message(current, stage))

    st.link_button(
        "💬 OPEN SMS — MESSAGE READY",
        _payment_reminder_sms_url(current, stage),
        type="primary",
        use_container_width=True,
    )
    st.caption("Send it in your normal Messages app, then come back here and press SENT — NEXT.")

    sent_col, skip_col = st.columns(2)
    if sent_col.button(
        "✅ SENT — NEXT",
        type="primary",
        use_container_width=True,
        key=f"payment_reminder_sent_{index}",
    ):
        if _admin_mark_payment_reminder_sent(current):
            st.session_state["payment_reminder_sent_count"] = sent_count + 1
            st.session_state["payment_reminder_index"] = index + 1
            st.rerun()
        else:
            st.error("The reminder status could not be saved. Do not move on yet; please try again.")

    if skip_col.button(
        "⏭️ SKIP",
        use_container_width=True,
        key=f"payment_reminder_skip_{index}",
    ):
        st.session_state["payment_reminder_index"] = index + 1
        st.rerun()

    if st.button("↩️ End / reload queue", use_container_width=True, key="payment_reminder_end"):
        _payment_phone_reset_session()
        st.rerun()

    st.stop()


# ============================================================
# ADMIN PHONE REMINDER SEND MODE
# ============================================================
# This is a separate Admin utility reached only with ?phone_reminders=1.
# It stops before the normal Driver front, so Driver and the route engine remain unchanged.
if PHONE_REMINDER_MODE:
    st.title("📱 DanCleanUK — Reminder Sender")
    st.caption("Send tomorrow's prepared reminders through this phone's normal Messages app")

    if not _admin_customer_table_ready():
        st.error("Customer storage is not available.")
        st.stop()
    if not _admin_reminder_columns_ready():
        st.error("Reminder history storage is not ready yet.")
        st.stop()
    if not _admin_reminder_queue_columns_ready():
        st.error("Phone reminder queue storage is not ready yet. Run the supplied one-time Supabase SQL.")
        st.stop()

    london_today = datetime.now(ZoneInfo("Europe/London")).date()
    phone_tomorrow = (pd.Timestamp(london_today) + pd.Timedelta(days=1)).date()
    phone_date_str = phone_tomorrow.isoformat()

    # A queue is intentionally local to the phone session after Start Sending.
    # This keeps the sequence stable while each sent customer is removed from Supabase.
    active_queue = st.session_state.get("phone_reminder_active_queue")
    if st.session_state.get("phone_reminder_queue_date") != phone_date_str:
        _phone_reminder_reset_session()
        active_queue = None

    if not active_queue:
        queued = _admin_load_phone_reminder_queue(phone_date_str)
        valid_queue = []
        for row in queued:
            due = clean_val(row.get("next_cleaning_due"))
            planned = clean_val(row.get("planned_service_date"))
            scheduled = planned or due
            if scheduled != phone_date_str:
                continue
            phone = clean_val(row.get("phone"))
            if not phone:
                continue
            valid_queue.append({
                "Customer ID": row.get("id"),
                "Address": clean_val(row.get("address")) or "Customer",
                "Postcode": normalise_postcode(row.get("postcode")),
                "Phone": phone,
                "Reminder Sent For": clean_val(row.get("reminder_sent_for")),
                "Reminder Sent At": clean_val(row.get("reminder_sent_at")),
            })

        st.subheader(f"Tomorrow · {phone_tomorrow.strftime('%d/%m/%Y')}")
        if not valid_queue:
            st.info("No reminders are prepared for tomorrow. Prepare the selected customers in Admin on the laptop first.")
            st.markdown("You can keep this page bookmarked on your phone and refresh it after preparing the queue.")
            if st.button("🔄 Refresh", use_container_width=True):
                st.rerun()
            st.stop()

        st.success(f"{len(valid_queue)} customer reminder(s) ready on this phone.")
        with st.expander("Preview message", expanded=False):
            st.write(_admin_reminder_message())

        for row in valid_queue:
            already_sent = row["Reminder Sent For"] == phone_date_str
            with st.container(border=True):
                st.markdown(f"**{row['Address']}**")
                st.caption(f"{row['Postcode']} · 📞 {row['Phone']}")
                if already_sent:
                    st.warning("This customer already has a reminder recorded for tomorrow. They are still in the queue because Admin deliberately selected them again.")

        if st.button(
            f"▶️ START SENDING {len(valid_queue)} REMINDER(S)",
            type="primary",
            use_container_width=True,
            key="phone_reminder_start",
        ):
            st.session_state["phone_reminder_active_queue"] = valid_queue
            st.session_state["phone_reminder_queue_date"] = phone_date_str
            st.session_state["phone_reminder_index"] = 0
            st.session_state["phone_reminder_sent_count"] = 0
            st.rerun()
        st.stop()

    queue = st.session_state.get("phone_reminder_active_queue", [])
    index = int(st.session_state.get("phone_reminder_index", 0))
    sent_count = int(st.session_state.get("phone_reminder_sent_count", 0))

    if index >= len(queue):
        st.success(f"✅ Reminder session finished. {sent_count} marked as sent.")
        remaining = _admin_load_phone_reminder_queue(phone_date_str)
        if remaining:
            st.info(f"{len(remaining)} customer(s) are still in the prepared queue — for example jobs you skipped.")
        else:
            st.info("No customers remain in tomorrow's prepared reminder queue.")
        if st.button("🔄 RELOAD REMAINING QUEUE", type="primary", use_container_width=True):
            _phone_reminder_reset_session()
            st.rerun()
        st.stop()

    current = queue[index]
    st.progress((index + 1) / max(1, len(queue)))
    st.caption(f"Customer {index + 1} of {len(queue)} · {sent_count} marked sent")
    st.markdown(f"### {current['Address']}")
    st.write(current["Postcode"])
    st.write(f"📞 {current['Phone']}")

    with st.expander("Message", expanded=True):
        st.write(_admin_reminder_message())

    st.link_button(
        "💬 OPEN SMS — MESSAGE READY",
        _admin_reminder_sms_url(current["Phone"]),
        type="primary",
        use_container_width=True,
    )
    st.caption("Send it in your normal Messages app, then come back here and press SENT — NEXT.")

    sent_col, skip_col = st.columns(2)
    if sent_col.button(
        "✅ SENT — NEXT",
        type="primary",
        use_container_width=True,
        key=f"phone_reminder_sent_{index}",
    ):
        if _admin_mark_reminder_sent(current["Customer ID"], phone_date_str):
            _admin_clear_phone_reminder_queue_customer(current["Customer ID"])
            st.session_state["phone_reminder_sent_count"] = sent_count + 1
            st.session_state["phone_reminder_index"] = index + 1
            st.rerun()
        else:
            st.error("The reminder status could not be saved. Do not move on yet; please try again.")

    if skip_col.button(
        "⏭️ SKIP",
        use_container_width=True,
        key=f"phone_reminder_skip_{index}",
    ):
        st.session_state["phone_reminder_index"] = index + 1
        st.rerun()

    if st.button("↩️ End / reload queue", use_container_width=True, key="phone_reminder_end"):
        _phone_reminder_reset_session()
        st.rerun()

    st.stop()


if st.session_state.get("admin_office_view", False):
    st.title("🏢 DanCleanUK — Admin Dashboard")
    st.caption("Office management")

    if st.button("🚗 Return to Driver / Route App", type="primary", use_container_width=True):
        st.session_state["admin_office_view"] = False
        st.rerun()

    st.markdown("---")
    admin_tab = st.radio(
        "Admin section",
        ["📅 Upcoming Work / Planner", "💷 Outstanding Payments", "🚐 Prepare Route", "📊 Daily Reports", "👥 Customers"],
        horizontal=True,
        label_visibility="collapsed",
        key="admin_dashboard_section",
    )
    routes = _admin_load_saved_routes()

    # Close any one-off moved jobs that have already been completed. This only
    # refreshes Admin customer scheduling data; saved routes and Driver data are untouched.
    if _admin_planned_service_column_ready():
        _admin_sync_completed_planned_jobs(routes)

    with st.expander("📂 Open Saved Route on Laptop", expanded=False):
        st.caption("Choose any saved route date and open the permanent Supabase route on this laptop.")
        saved_route_date = st.date_input(
            "Saved route date",
            value=datetime.now(ZoneInfo("Europe/London")).date(),
            key="admin_saved_route_date",
        )
        saved_route_str = saved_route_date.isoformat()
        saved_snapshot = load_route_snapshot(saved_route_str)
        if saved_snapshot is not None:
            s1, s2, s3 = st.columns(3)
            s1.metric("Jobs", int(saved_snapshot.get("jobs") or 0))
            s2.metric("Miles", f"{float(saved_snapshot.get('miles') or 0):.1f}")
            total_minutes = int(round(float(saved_snapshot.get("time_s") or 0) / 60.0))
            s3.metric("Driving", f"{total_minutes // 60}h {total_minutes % 60:02d}m")
            if st.button(
                "📂 LOAD SAVED ROUTE",
                type="primary",
                use_container_width=True,
                key="admin_load_saved_route_laptop",
            ):
                st.session_state["service_date"] = saved_route_str
                ok, message = apply_saved_route_snapshot(saved_route_str)
                if ok:
                    st.session_state["admin_office_view"] = False
                    st.session_state["replace_saved_route_allowed"] = False
                    st.session_state.pop("start_new_day_mode", None)
                    st.rerun()
                else:
                    st.error(message)
        else:
            st.info("No permanent saved route exists for this date.")

    if admin_tab == "📅 Upcoming Work / Planner":
        st.header("📅 Upcoming Work / Planner")
        st.caption("Plan upcoming cleans, move one-off jobs earlier or later, and send tomorrow reminders")

        if not _admin_customer_table_ready():
            st.info("Customer storage is not ready yet.")
        else:
            move_ready = _admin_planned_service_column_ready()
            reminder_status_ready = _admin_reminder_columns_ready()
            reminder_queue_ready = _admin_reminder_queue_columns_ready()

            if not move_ready:
                st.warning(
                    "Manual job moves are not enabled yet. Run the supplied one-time Supabase "
                    "planned-service-date setup SQL, then refresh this page."
                )

            if not reminder_status_ready:
                st.warning(
                    "Reminder history is not enabled yet. Run the supplied one-time reminder-status "
                    "Supabase SQL before using direct or bulk SMS."
                )

            if not reminder_queue_ready:
                st.warning(
                    "Phone reminder queue is not enabled yet. Run the supplied one-time phone-queue "
                    "Supabase SQL, then refresh this page."
                )

            customer_records = _admin_load_customer_records(active_only=True)
            upcoming_records = []
            for row in customer_records:
                due = clean_val(row.get("next_cleaning_due"))
                planned = clean_val(row.get("planned_service_date"))
                scheduled = planned or due
                if not scheduled:
                    continue
                upcoming_records.append({
                    "Customer ID": row.get("id"),
                    "Address": clean_val(row.get("address")),
                    "Postcode": normalise_postcode(row.get("postcode")),
                    "Price": float(row.get("price", 0) or 0),
                    "Phone": clean_val(row.get("phone")),
                    "Cleaning Plan": normalise_cleaning_plan(row.get("cleaning_plan")),
                    "Notes": clean_val(row.get("notes")),
                    "Next Cleaning Due": due,
                    "Planned Service Date": planned,
                    "Scheduled Date": scheduled,
                    "Reminder Sent For": clean_val(row.get("reminder_sent_for")),
                    "Reminder Sent At": clean_val(row.get("reminder_sent_at")),
                })

            if not upcoming_records:
                st.info("No customers currently have upcoming work scheduled.")
            else:
                planner_df = pd.DataFrame(upcoming_records)
                planner_df["_scheduled"] = pd.to_datetime(planner_df["Scheduled Date"], errors="coerce").dt.date
                planner_df = planner_df[planner_df["_scheduled"].notna()].copy()
                today = datetime.now(ZoneInfo("Europe/London")).date()
                tomorrow = (pd.Timestamp(today) + pd.Timedelta(days=1)).date()
                week_end = (pd.Timestamp(today) + pd.Timedelta(days=7)).date()

                def _admin_due_group(due):
                    if due < today:
                        return "Overdue"
                    if due == today:
                        return "Due Today"
                    if due == tomorrow:
                        return "Due Tomorrow"
                    if due <= week_end:
                        return "Due This Week"
                    return "Later"

                def _render_move_controls(row, key_prefix):
                    customer_id = row.get("Customer ID")
                    original_raw = clean_val(row.get("Next Cleaning Due"))
                    planned_raw = clean_val(row.get("Planned Service Date"))
                    if customer_id in (None, "") or not original_raw:
                        return
                    try:
                        original_due = pd.to_datetime(original_raw).date()
                    except Exception:
                        return

                    editor_key = f"admin_move_editor_{customer_id}"
                    planned_date = None
                    if planned_raw:
                        try:
                            planned_date = pd.to_datetime(planned_raw).date()
                        except Exception:
                            planned_date = None

                    if planned_date:
                        direction = "forward" if planned_date < original_due else "back"
                        st.caption(
                            f"📆 One-off move {direction}: {planned_date.strftime('%d/%m/%Y')} "
                            f"· regular due {original_due.strftime('%d/%m/%Y')}"
                        )
                        b1, b2 = st.columns(2)
                        if b1.button(
                            "✏️ Change Move",
                            key=f"{key_prefix}_change_{customer_id}",
                            use_container_width=True,
                            disabled=not move_ready,
                        ):
                            st.session_state[editor_key] = True
                            st.rerun()
                        if b2.button(
                            "↩️ Cancel Move",
                            key=f"{key_prefix}_cancel_{customer_id}",
                            use_container_width=True,
                            disabled=not move_ready,
                        ):
                            if _admin_clear_planned_service_date(customer_id):
                                st.session_state.pop(editor_key, None)
                                st.rerun()
                            else:
                                st.error("Could not cancel this move. Please try again.")
                    else:
                        if st.button(
                            "📆 Move Job",
                            key=f"{key_prefix}_open_{customer_id}",
                            use_container_width=True,
                            disabled=not move_ready,
                            help="Move this one clean earlier or later without changing the customer's regular cleaning plan.",
                        ):
                            st.session_state[editor_key] = True
                            st.rerun()

                    if st.session_state.get(editor_key):
                        current_planned = planned_date
                        default_date = current_planned or original_due
                        if default_date < today:
                            default_date = today
                        latest_allowed = (pd.Timestamp(today) + pd.DateOffset(years=1)).date()
                        if default_date > latest_allowed:
                            default_date = latest_allowed

                        new_date = st.date_input(
                            "Move this job to",
                            value=default_date,
                            min_value=today,
                            max_value=latest_allowed,
                            key=f"{key_prefix}_date_{customer_id}",
                            help=(
                                "This changes only this one clean. The customer's regular Next Cleaning Due "
                                "date and cleaning plan stay unchanged."
                            ),
                        )
                        c1, c2 = st.columns(2)
                        if c1.button(
                            "💾 Save Move",
                            type="primary",
                            key=f"{key_prefix}_save_{customer_id}",
                            use_container_width=True,
                        ):
                            if new_date == original_due:
                                ok = _admin_clear_planned_service_date(customer_id)
                            else:
                                ok = _admin_set_planned_service_date(customer_id, new_date)
                            if ok:
                                st.session_state.pop(editor_key, None)
                                st.rerun()
                            else:
                                st.error("Could not save this move. Please try again.")
                        if c2.button(
                            "Cancel",
                            key=f"{key_prefix}_dismiss_{customer_id}",
                            use_container_width=True,
                        ):
                            st.session_state.pop(editor_key, None)
                            st.rerun()

                planner_df["Due"] = planner_df["_scheduled"].map(_admin_due_group)
                visible = planner_df[planner_df["Due"] != "Later"].copy()
                counts = visible["Due"].value_counts() if not visible.empty else {}

                c1, c2, c3, c4 = st.columns(4)
                c1.metric("Overdue", int(counts.get("Overdue", 0)))
                c2.metric("Today", int(counts.get("Due Today", 0)))
                c3.metric("Tomorrow", int(counts.get("Due Tomorrow", 0)))
                c4.metric("Next 7 Days", int(len(visible)))

                if visible.empty:
                    next_due = planner_df["_scheduled"].min() if not planner_df.empty else None
                    st.info(
                        f"Nothing is due in the next 7 days. Next scheduled: {next_due.strftime('%d/%m/%Y')}"
                        if next_due else "No work is due yet."
                    )
                else:
                    st.metric("Due work value", f"£{float(visible['Price'].sum()):.2f}")

                    tomorrow_rows = visible[visible["Due"] == "Due Tomorrow"].copy()
                    if not tomorrow_rows.empty:
                        tomorrow_rows = tomorrow_rows.sort_values(
                            ["Postcode", "Address"], na_position="last"
                        ).reset_index(drop=True)

                        st.subheader("🔔 Tomorrow — reminders")
                        st.caption(
                            f"Tomorrow: {len(tomorrow_rows)} customer(s). Tick only the customers you want to message. "
                            "Unticking a customer does not remove them from tomorrow's work."
                        )

                        with st.expander("Preview standard reminder message", expanded=False):
                            st.write(_admin_reminder_message())

                        if st.session_state.pop("admin_reminder_send_notice", None):
                            notice = st.session_state.pop("admin_reminder_send_notice_text", "")
                            if notice:
                                st.success(notice)
                        if st.session_state.pop("admin_reminder_send_error", None):
                            error_text = st.session_state.pop("admin_reminder_send_error_text", "")
                            if error_text:
                                st.error(error_text)

                        eligible_keys = []
                        for _, row in tomorrow_rows.iterrows():
                            customer_id = clean_val(row.get("Customer ID"))
                            phone = clean_val(row.get("Phone"))
                            if customer_id and phone:
                                eligible_keys.append(
                                    f"admin_reminder_select_{customer_id}_{tomorrow.isoformat()}"
                                )

                        sel1, sel2 = st.columns(2)
                        if sel1.button(
                            "✅ Select Unsent",
                            use_container_width=True,
                            key="admin_reminder_select_unsent",
                        ):
                            for _, row in tomorrow_rows.iterrows():
                                customer_id = clean_val(row.get("Customer ID"))
                                phone = clean_val(row.get("Phone"))
                                if not customer_id or not phone:
                                    continue
                                sent_for = clean_val(row.get("Reminder Sent For"))
                                key = f"admin_reminder_select_{customer_id}_{tomorrow.isoformat()}"
                                st.session_state[key] = sent_for != tomorrow.isoformat()
                            st.rerun()

                        if sel2.button(
                            "⬜ Clear All",
                            use_container_width=True,
                            key="admin_reminder_clear_all",
                        ):
                            for key in eligible_keys:
                                st.session_state[key] = False
                            st.rerun()

                        selected_customers = []
                        for reminder_idx, (_, row) in enumerate(tomorrow_rows.iterrows()):
                            customer_id = clean_val(row.get("Customer ID"))
                            address = clean_val(row.get("Address")) or "Customer"
                            postcode = normalise_postcode(row.get("Postcode"))
                            phone = clean_val(row.get("Phone"))
                            sent_for = clean_val(row.get("Reminder Sent For"))
                            sent_at = clean_val(row.get("Reminder Sent At"))
                            already_sent = sent_for == tomorrow.isoformat()
                            select_key = f"admin_reminder_select_{customer_id}_{tomorrow.isoformat()}"

                            if select_key not in st.session_state:
                                st.session_state[select_key] = bool(phone) and not already_sent

                            with st.container(border=True):
                                tick_col, detail_col, action_col = st.columns([1, 5, 2])
                                selected_now = tick_col.checkbox(
                                    "Send",
                                    key=select_key,
                                    disabled=not bool(phone),
                                    label_visibility="collapsed",
                                )
                                detail_col.markdown(f"**{address}**  \n{postcode}")
                                if phone:
                                    detail_col.caption(f"📞 {phone}")
                                else:
                                    detail_col.caption("⚠️ No phone number")

                                if already_sent:
                                    sent_label = "Reminder sent"
                                    if sent_at:
                                        try:
                                            sent_dt = pd.to_datetime(sent_at, utc=True).tz_convert("Europe/London")
                                            sent_label += f" · {sent_dt.strftime('%d/%m/%Y %H:%M')}"
                                        except Exception:
                                            pass
                                    action_col.success("✅ " + sent_label)
                                elif phone:
                                    action_col.caption("Not sent yet")

                                if phone:
                                    action_col.link_button(
                                        "💬 Open SMS",
                                        _admin_reminder_sms_url(phone),
                                        use_container_width=True,
                                    )

                                _render_move_controls(row, f"tomorrow_{reminder_idx}")

                            if selected_now and phone:
                                selected_customers.append({
                                    "Customer ID": customer_id,
                                    "Address": address,
                                    "Phone": phone,
                                })

                        selected_count = len(selected_customers)
                        st.markdown("---")

                        prepare_disabled = (
                            selected_count == 0
                            or not reminder_status_ready
                            or not reminder_queue_ready
                        )
                        if st.button(
                            f"📱 PREPARE {selected_count} REMINDER(S) FOR PHONE",
                            type="primary",
                            use_container_width=True,
                            disabled=prepare_disabled,
                            key="admin_prepare_phone_reminders",
                        ):
                            selected_ids = [x["Customer ID"] for x in selected_customers]
                            ok, detail = _admin_prepare_phone_reminder_queue(
                                selected_ids, tomorrow.isoformat()
                            )
                            if ok:
                                st.session_state["admin_phone_queue_notice"] = (
                                    f"✅ Phone reminder queue ready for {detail} customer(s)."
                                )
                            else:
                                st.session_state["admin_phone_queue_error"] = str(detail)
                            st.rerun()

                        if selected_count == 0:
                            st.caption("Tick at least one customer to prepare the phone reminder queue.")
                        elif not reminder_status_ready:
                            st.caption("Reminder history storage must be enabled first.")
                        elif not reminder_queue_ready:
                            st.caption("Run the one-time phone reminder queue SQL first.")
                        else:
                            st.caption(
                                "This saves exactly the customers currently ticked. Unticked customers will not appear in Phone Reminder Mode."
                            )

                        phone_queue_notice = st.session_state.pop("admin_phone_queue_notice", "")
                        if phone_queue_notice:
                            st.success(phone_queue_notice)
                            st.markdown(
                                f"**On your phone open:** [{PHONE_REMINDER_URL}]({PHONE_REMINDER_URL})"
                            )
                            st.caption("Bookmark that page on your phone — the same link can be reused every day.")

                        phone_queue_error = st.session_state.pop("admin_phone_queue_error", "")
                        if phone_queue_error:
                            st.error(phone_queue_error)

                    # Tomorrow is already shown above, so do not repeat it here.
                    other_rows = visible[visible["Due"] != "Due Tomorrow"].copy()
                    if not other_rows.empty:
                        st.subheader("📅 Other work due in the next 7 days")
                        st.caption(
                            "Use Move Job to bring work forward or push a one-off clean back. "
                            "The customer's regular cleaning plan is not changed."
                        )
                        for work_idx, (_, row) in enumerate(
                            other_rows.sort_values(
                                ["_scheduled", "Postcode", "Address"], na_position="last"
                            ).iterrows()
                        ):
                            address = clean_val(row.get("Address")) or "Customer"
                            postcode = normalise_postcode(row.get("Postcode"))
                            phone = clean_val(row.get("Phone")) or "—"
                            due_group = clean_val(row.get("Due"))
                            price = float(row.get("Price", 0) or 0)
                            plan = normalise_cleaning_plan(row.get("Cleaning Plan")) or "No plan"
                            notes = clean_val(row.get("Notes"))
                            try:
                                due_label = pd.to_datetime(row.get("Scheduled Date")).strftime("%d/%m/%Y")
                            except Exception:
                                due_label = clean_val(row.get("Scheduled Date")) or "—"

                            with st.container(border=True):
                                left, middle, right = st.columns([4, 2, 2])
                                left.markdown(f"**{address}**  \n{postcode} · 📞 {phone}")
                                middle.markdown(f"**{due_group}**  \n{due_label} · {plan}")
                                right.markdown(f"**£{price:.2f}**")
                                _render_move_controls(row, f"work_{work_idx}")
                                if notes:
                                    st.caption(f"Notes: {notes}")

    elif admin_tab == "💷 Outstanding Payments":
        st.header("💷 Outstanding Payments")
        st.caption("Completed cleans still waiting for payment. Payment reminders become due from Day 3 and Day 7; Day 14+ stays flagged for your attention.")

        today = datetime.now(ZoneInfo("Europe/London")).date()
        jobs = _admin_jobs_from_routes(routes)
        outstanding = []
        for job in jobs:
            status = clean_val(job.get("Status")).lower()
            payment = clean_val(job.get("Payment"))
            if status == "completed" and payment in {"Bank Transfer", "Not Paid"}:
                item = dict(job)
                item["_service_day"] = _payment_service_date(item)
                item["_age_days"] = (
                    max(0, (today - item["_service_day"]).days)
                    if item["_service_day"] is not None else 0
                )
                item["_reminder_stage"] = _payment_reminder_stage(item, today)
                outstanding.append(item)

        if not outstanding:
            st.success("✅ No outstanding payments.")
        else:
            total = sum(float(x.get("Price", 0) or 0) for x in outstanding)
            reminder_due_jobs = [x for x in outstanding if x.get("_reminder_stage") in (3, 7)]
            # Never prepare two SMS messages for the same customer in one batch.
            # Individual debts remain visible below in All outstanding.
            reminder_due = _dedupe_payment_reminders(reminder_due_jobs)
            attention = [x for x in outstanding if x.get("_reminder_stage") == 14]

            m1, m2, m3, m4 = st.columns(4)
            m1.metric("Outstanding", f"£{total:.2f}")
            m2.metric("Unpaid jobs", len(outstanding))
            m3.metric("Reminders due", len(reminder_due))
            m4.metric("Needs attention", len(attention))

            if attention:
                st.subheader("🚨 Needs Attention · 14+ days")
                st.caption("These stay here until you mark them paid or deal with them manually. No automatic third reminder is sent.")
                for job in sorted(attention, key=lambda x: (-x.get("_age_days", 0), x.get("_route_date", ""))):
                    address = clean_val(job.get("Address")) or clean_val(job.get("address_text")) or clean_val(job.get("Postcode"))
                    amount = float(job.get("Price", 0) or 0)
                    service_day = job.get("_service_day")
                    service_display = service_day.strftime("%d/%m/%Y") if service_day else clean_val(job.get("_route_date"))
                    with st.container(border=True):
                        c1, c2, c3 = st.columns([4, 2, 2])
                        c1.markdown(f"**{address}**  \n{normalise_postcode(job.get('Postcode'))} · Cleaned {service_display}")
                        c2.markdown(f"**£{amount:.2f}**  \n🚨 {job.get('_age_days', 0)} days outstanding")
                        if c3.button("✅ Mark Paid", key=f"attention_paid_{job.get('_route_date')}_{job.get('job_id')}", use_container_width=True):
                            if _admin_mark_job_paid(job.get("_route_date"), job.get("job_id")):
                                st.rerun()
                            else:
                                st.error("Could not update this payment. Please try again.")

            st.subheader("🔔 Payment reminders")
            if not reminder_due:
                st.info("No Day 3 or Day 7 payment reminders are due right now.")
            else:
                st.caption("Tick the customers you want to contact. Unticking a customer leaves the debt outstanding but excludes them from this phone reminder batch.")

                if st.button("✅ Select Due", use_container_width=True, key="payment_select_due"):
                    for job in reminder_due:
                        key = f"payment_pick_{job.get('_route_date')}_{job.get('job_id')}_{job.get('_reminder_stage')}"
                        st.session_state[key] = bool(clean_val(job.get("Phone")))
                    st.rerun()
                if st.button("⬜ Clear All", use_container_width=True, key="payment_clear_due"):
                    for job in reminder_due:
                        key = f"payment_pick_{job.get('_route_date')}_{job.get('job_id')}_{job.get('_reminder_stage')}"
                        st.session_state[key] = False
                    st.rerun()

                selected = []
                for job in sorted(reminder_due, key=lambda x: (x.get("_reminder_stage", 0), x.get("_route_date", ""), clean_val(x.get("address_text")))):
                    address = clean_val(job.get("Address")) or clean_val(job.get("address_text")) or clean_val(job.get("Postcode"))
                    amount = float(job.get("Price", 0) or 0)
                    phone = clean_val(job.get("Phone"))
                    stage = int(job.get("_reminder_stage", 3))
                    service_day = job.get("_service_day")
                    service_display = service_day.strftime("%d/%m/%Y") if service_day else clean_val(job.get("_route_date"))
                    pick_key = f"payment_pick_{job.get('_route_date')}_{job.get('job_id')}_{stage}"
                    if pick_key not in st.session_state:
                        st.session_state[pick_key] = bool(phone)

                    with st.container(border=True):
                        c1, c2, c3 = st.columns([1, 5, 2])
                        picked = c1.checkbox(
                            "Select",
                            key=pick_key,
                            disabled=not bool(phone),
                            label_visibility="collapsed",
                        )
                        c2.markdown(
                            f"**{address}**  \n{normalise_postcode(job.get('Postcode'))} · 📞 {phone or 'No phone'}  \n"
                            f"Cleaned {service_display} · **£{amount:.2f}**"
                        )
                        c3.markdown(f"**Day {stage}**  \n{job.get('_age_days', 0)} days")
                        if stage == 7:
                            sent_at = clean_val(job.get("PaymentReminderDay3SentAt"))
                            if sent_at:
                                try:
                                    sent_display = pd.to_datetime(sent_at, utc=True).tz_convert("Europe/London").strftime("%d/%m %H:%M")
                                    st.caption(f"First reminder sent {sent_display}")
                                except Exception:
                                    st.caption("First reminder already sent")
                        if picked and phone:
                            selected.append(job)

                if selected:
                    if st.button(
                        f"📱 PREPARE {len(selected)} PAYMENT REMINDER(S) FOR PHONE",
                        type="primary",
                        use_container_width=True,
                        key="prepare_payment_phone_queue",
                    ):
                        ok, result = _admin_prepare_payment_reminder_queue(selected)
                        if ok:
                            st.session_state["payment_queue_notice"] = f"Payment reminder queue ready for {result} customer(s)."
                            st.rerun()
                        else:
                            st.error(str(result))
                else:
                    st.button(
                        "📱 PREPARE PAYMENT REMINDERS FOR PHONE",
                        disabled=True,
                        use_container_width=True,
                        key="prepare_payment_phone_queue_disabled",
                    )

                payment_notice = st.session_state.pop("payment_queue_notice", "")
                if payment_notice:
                    st.success(payment_notice)
                    st.markdown(f"**On your phone open this special payment link:** [{PAYMENT_REMINDER_URL}]({PAYMENT_REMINDER_URL})")
                    st.caption("Important: do not open the normal DanCleanUK home-screen icon for this step — that intentionally opens Driver. Bookmark this special payment-reminder link separately on your phone and reuse it.")

            st.subheader("🧾 All outstanding")
            for job in sorted(outstanding, key=lambda x: (x.get("_route_date", ""), clean_val(x.get("address_text"))), reverse=True):
                address = clean_val(job.get("Address")) or clean_val(job.get("address_text")) or clean_val(job.get("Postcode"))
                amount = float(job.get("Price", 0) or 0)
                payment = clean_val(job.get("Payment"))
                service_day = job.get("_service_day")
                service_display = service_day.strftime("%d/%m/%Y") if service_day else clean_val(job.get("_route_date"))
                age = int(job.get("_age_days", 0) or 0)
                with st.container(border=True):
                    c1, c2, c3 = st.columns([4, 2, 2])
                    c1.markdown(f"**{address}**  \n{normalise_postcode(job.get('Postcode'))} · Cleaned {service_display}")
                    c2.markdown(f"**£{amount:.2f}**  \n{payment} · {age} day{'s' if age != 1 else ''}")
                    if c3.button("✅ Mark Paid", key=f"admin_paid_{job.get('_route_date')}_{job.get('job_id')}", use_container_width=True):
                        if _admin_mark_job_paid(job.get("_route_date"), job.get("job_id")):
                            st.rerun()
                        else:
                            st.error("Could not update this payment. Please try again.")

    elif admin_tab == "🚐 Prepare Route":
        st.header("🚐 Prepare Route")
        st.caption("Select permanent customers here, then send them into the existing locked route optimiser. No spreadsheet is needed for the normal daily workflow.")

        if not _admin_customer_table_ready():
            st.error("Customer storage is not ready yet.")
        else:
            route_customers = _admin_load_customer_records(active_only=True)
            if not route_customers:
                st.info("No active customers are available. Add customers in 👥 Customers first.")
            else:
                london_today = datetime.now(ZoneInfo("Europe/London")).date()
                default_route_date = london_today + pd.Timedelta(days=1)
                target_route_date = st.date_input(
                    "Route date",
                    value=default_route_date,
                    key="admin_prepare_route_date",
                )
                target_route_str = target_route_date.isoformat()

                # ADMIN ONLY — safe correction workflow for a route that was locked by mistake.
                # The existing permanent Supabase route is NEVER deleted here. It remains the
                # fallback until an adjusted route has gone through the normal optimiser and the
                # user deliberately presses SAVE / LOCK THIS ROUTE FOR PHONE again.
                existing_saved_route = load_route_snapshot(target_route_str)
                route_locked = existing_saved_route is not None
                adjustment_active = bool(
                    route_locked
                    and st.session_state.get("admin_adjust_saved_route_date") == target_route_str
                )

                saved_route_jobs = []
                saved_route_identities = set()
                saved_completed = 0
                saved_payment_started = 0
                saved_report_exists = False

                if route_locked:
                    saved_route_jobs = list(existing_saved_route.get("jobs_data") or [])
                    for saved_job in saved_route_jobs:
                        saved_address = clean_val(saved_job.get("Address")) or clean_val(saved_job.get("address_text"))
                        saved_postcode = normalise_postcode(saved_job.get("Postcode"))
                        if saved_address or saved_postcode:
                            saved_route_identities.add(
                                _admin_customer_identity(saved_address, saved_postcode)
                            )
                        if clean_val(saved_job.get("Status")).lower() == "completed":
                            saved_completed += 1
                        saved_payment = clean_val(saved_job.get("Payment"))
                        if saved_payment and saved_payment.lower() != "waiting":
                            saved_payment_started += 1
                    saved_report_exists = bool(existing_saved_route.get("report_b64"))

                    saved_minutes = int(round(float(existing_saved_route.get("time_s") or 0) / 60.0))
                    s1, s2, s3 = st.columns(3)
                    s1.metric("Saved jobs", int(existing_saved_route.get("jobs") or len(saved_route_jobs)))
                    s2.metric("Saved miles", f"{float(existing_saved_route.get('miles') or 0):.1f}")
                    s3.metric("Saved driving", f"{saved_minutes // 60}h {saved_minutes % 60:02d}m")

                    # ADMIN ONLY: a saved route can always be corrected, but routes that already
                    # contain working-day progress require a second explicit confirmation. The old
                    # permanent route remains untouched until the replacement is optimised and saved.
                    route_has_work_progress = bool(
                        saved_completed > 0
                        or saved_report_exists
                    )
                    progress_confirm_pending = bool(
                        route_locked
                        and st.session_state.get("admin_adjust_confirm_progress_date") == target_route_str
                        and not adjustment_active
                    )

                    if adjustment_active:
                        st.warning(
                            "✏️ ADJUSTMENT MODE — the current saved route is still protected in Supabase. "
                            "Tick or untick customers below, then send the corrected jobs to the existing optimiser. "
                            "Nothing replaces the old route until you deliberately SAVE / LOCK the new one."
                        )
                        if st.session_state.get("admin_adjust_progress_override_date") == target_route_str:
                            st.error(
                                "⚠️ ADMIN OVERRIDE ACTIVE — saving the replacement will reset the old route's "
                                "completion/payment progress and discard its saved Daily Report for this date."
                            )
                        if st.button(
                            "↩️ CANCEL ADJUSTMENT — KEEP SAVED ROUTE",
                            use_container_width=True,
                            key="admin_cancel_saved_route_adjustment",
                        ):
                            st.session_state.pop("admin_adjust_saved_route_date", None)
                            st.session_state.pop("admin_adjust_confirm_progress_date", None)
                            st.session_state.pop("admin_adjust_progress_override_date", None)
                            st.session_state.pop("admin_replacement_clear_report", None)
                            st.session_state["replace_saved_route_allowed"] = False
                            st.rerun()
                    else:
                        st.warning(
                            "A permanent saved route already exists for this date. It is protected and will not be "
                            "overwritten unless you deliberately adjust, optimise and save a replacement."
                        )
                        st.caption(
                            "Saved by mistake or need to add/remove a customer? Use the button below. "
                            "The current saved route stays safe while you make the correction."
                        )

                        if progress_confirm_pending:
                            progress_bits = []
                            if saved_completed:
                                progress_bits.append(f"{saved_completed} completed job(s)")
                            if saved_report_exists:
                                progress_bits.append("a saved Daily Report")
                            progress_text = " and ".join(progress_bits) or "working-day progress"
                            st.error(
                                f"⚠️ This route contains {progress_text}. You can still adjust it, but if you later "
                                "SAVE / LOCK the replacement, that old progress/report will be treated as superseded. "
                                "The current saved route remains safe until that final save."
                            )
                            c_confirm, c_cancel = st.columns(2)
                            if c_confirm.button(
                                "⚠️ YES — RESET & ADJUST",
                                type="primary",
                                use_container_width=True,
                                key=f"admin_confirm_saved_route_adjustment_{target_route_str}",
                            ):
                                st.session_state["admin_adjust_saved_route_date"] = target_route_str
                                st.session_state["admin_adjust_progress_override_date"] = target_route_str
                                st.session_state.pop("admin_adjust_confirm_progress_date", None)
                                st.session_state["replace_saved_route_allowed"] = False
                                st.session_state["admin_prepare_route_filter"] = "All active customers"
                                st.rerun()
                            if c_cancel.button(
                                "Cancel",
                                use_container_width=True,
                                key=f"admin_cancel_progress_adjustment_{target_route_str}",
                            ):
                                st.session_state.pop("admin_adjust_confirm_progress_date", None)
                                st.session_state.pop("admin_adjust_progress_override_date", None)
                                st.rerun()
                        else:
                            if st.button(
                                "✏️ ADJUST SAVED ROUTE",
                                type="primary",
                                use_container_width=True,
                                key=f"admin_begin_saved_route_adjustment_{target_route_str}",
                            ):
                                if route_has_work_progress:
                                    st.session_state["admin_adjust_confirm_progress_date"] = target_route_str
                                else:
                                    st.session_state["admin_adjust_saved_route_date"] = target_route_str
                                    st.session_state.pop("admin_adjust_progress_override_date", None)
                                    st.session_state["admin_prepare_route_filter"] = "All active customers"
                                st.session_state["replace_saved_route_allowed"] = False
                                st.rerun()

                        if route_has_work_progress and not progress_confirm_pending:
                            reason_bits = []
                            if saved_completed:
                                reason_bits.append(f"{saved_completed} completed job(s)")
                            if saved_report_exists:
                                reason_bits.append("saved Daily Report")
                            st.info(
                                "This route already contains " + " and ".join(reason_bits) +
                                ". Adjustment is still available, but Admin will ask for confirmation first."
                            )

                route_rows = []
                for row in route_customers:
                    due_raw = clean_val(row.get("next_cleaning_due"))
                    planned_raw = clean_val(row.get("planned_service_date"))
                    effective_raw = planned_raw or due_raw
                    effective_date = None
                    if effective_raw:
                        try:
                            effective_date = pd.to_datetime(effective_raw).date()
                        except Exception:
                            effective_date = None
                    route_rows.append({
                        "Customer ID": row.get("id"),
                        "Address": clean_val(row.get("address")),
                        "Postcode": normalise_postcode(row.get("postcode")),
                        "Price": float(row.get("price", 0) or 0),
                        "Phone": clean_val(row.get("phone")),
                        "Cleaning Plan": normalise_cleaning_plan(row.get("cleaning_plan")),
                        "Next Cleaning Due": due_raw,
                        "Planned Service Date": planned_raw,
                        "Notes": clean_val(row.get("notes")),
                        "Zone": clean_val(row.get("zone")) or _admin_auto_zone(row.get("postcode")),
                        "_effective_date": effective_date,
                    })

                route_customer_df = pd.DataFrame(route_rows)
                zones = sorted({clean_val(x) or "Unzoned" for x in route_customer_df["Zone"].tolist()})

                # In adjustment mode tell the user if a job from the old route is no longer
                # present in the active customer book. The old route remains untouched if they cancel.
                if adjustment_active and saved_route_identities:
                    active_identities = {
                        _admin_customer_identity(row.get("Address"), row.get("Postcode"))
                        for _, row in route_customer_df.iterrows()
                    }
                    missing_saved_customers = saved_route_identities - active_identities
                    if missing_saved_customers:
                        st.warning(
                            f"{len(missing_saved_customers)} customer(s) from the saved route are no longer in the active "
                            "customer book, so they cannot be pre-selected here. Cancel adjustment if you need to keep "
                            "the original route exactly as saved."
                        )

                f1, f2 = st.columns([1, 2])
                selected_route_zone = f1.selectbox(
                    "Zone",
                    ["All zones"] + zones,
                    key="admin_prepare_route_zone",
                )
                route_search = f2.text_input(
                    "Search customers",
                    placeholder="Address, postcode or phone",
                    key="admin_prepare_route_search",
                ).strip().casefold()

                filter_mode = st.radio(
                    "Show",
                    ["Due / scheduled by route date", "All active customers"],
                    horizontal=True,
                    key="admin_prepare_route_filter",
                )

                visible_route_df = route_customer_df.copy()
                if selected_route_zone != "All zones":
                    visible_route_df = visible_route_df[
                        visible_route_df["Zone"].fillna("Unzoned") == selected_route_zone
                    ].copy()
                if route_search:
                    route_haystack = (
                        visible_route_df["Address"].fillna("").astype(str) + " " +
                        visible_route_df["Postcode"].fillna("").astype(str) + " " +
                        visible_route_df["Phone"].fillna("").astype(str)
                    ).str.casefold()
                    visible_route_df = visible_route_df[route_haystack.str.contains(route_search, regex=False)].copy()
                target_route_ts = pd.Timestamp(target_route_date).normalize()
                if filter_mode == "Due / scheduled by route date":
                    visible_due_series = pd.to_datetime(
                        visible_route_df["_effective_date"], errors="coerce"
                    ).dt.normalize()
                    visible_route_df = visible_route_df[
                        visible_due_series.notna() & (visible_due_series <= target_route_ts)
                    ].copy()

                due_series = pd.to_datetime(
                    route_customer_df["_effective_date"], errors="coerce"
                ).dt.normalize()
                due_count = int((due_series.notna() & (due_series <= target_route_ts)).sum())
                # Keep the summary business-friendly and independent from the route engine.
                m1, m2, m3 = st.columns(3)
                m1.metric("Active customers", len(route_customer_df))
                m2.metric("Due / overdue", due_count)
                m3.metric("Showing", len(visible_route_df))

                if visible_route_df.empty:
                    st.info("No customers match these route filters.")
                else:
                    visible_route_df = visible_route_df.sort_values(
                        ["Zone", "_effective_date", "Postcode", "Address"],
                        na_position="last",
                    ).reset_index(drop=True)
                    editor = visible_route_df[[
                        "Customer ID", "Address", "Postcode", "Zone", "Price", "Phone",
                        "Cleaning Plan", "Next Cleaning Due", "Planned Service Date", "Notes"
                    ]].copy()

                    select_all_shown = st.checkbox(
                        "Select all customers currently shown",
                        value=False,
                        key=f"admin_prepare_select_all_{target_route_str}_{selected_route_zone}_{filter_mode}_{'adjust' if adjustment_active else 'new'}",
                    )

                    if adjustment_active:
                        # Start from the currently saved route. This makes correction practical:
                        # remove an unwanted job or tick an extra customer, rather than rebuilding
                        # the selection from zero.
                        selected_flags = []
                        for _, editor_row in editor.iterrows():
                            identity = _admin_customer_identity(
                                editor_row.get("Address"), editor_row.get("Postcode")
                            )
                            selected_flags.append(identity in saved_route_identities)
                        if select_all_shown:
                            selected_flags = [True] * len(editor)
                        editor.insert(0, "Select", selected_flags)
                    else:
                        editor.insert(0, "Select", bool(select_all_shown))

                    edited_route = st.data_editor(
                        editor,
                        hide_index=True,
                        use_container_width=True,
                        disabled=[
                            "Customer ID", "Address", "Postcode", "Zone", "Price", "Phone",
                            "Cleaning Plan", "Next Cleaning Due", "Planned Service Date", "Notes"
                        ],
                        column_config={
                            "Select": st.column_config.CheckboxColumn("Select"),
                            "Customer ID": None,
                            "Price": st.column_config.NumberColumn("Price", format="£%.2f"),
                        },
                        # A separate editor state for normal preparation vs saved-route correction
                        # avoids stale checkbox selections leaking between the two workflows.
                        key=(
                            f"admin_prepare_route_editor_{target_route_str}_{selected_route_zone}_{filter_mode}_"
                            f"{'adjust' if adjustment_active else 'new'}_{int(bool(select_all_shown))}"
                        ),
                    )

                    selected_route_rows = edited_route[edited_route["Select"] == True].copy()
                    selected_route_value = float(selected_route_rows["Price"].sum()) if not selected_route_rows.empty else 0.0
                    st.caption(
                        f"Selected: {len(selected_route_rows)} job(s) · £{selected_route_value:.2f} · "
                        f"Route date {target_route_date.strftime('%d/%m/%Y')}"
                    )

                    adjustment_allowed = bool(route_locked and adjustment_active)
                    prepare_disabled = selected_route_rows.empty or (route_locked and not adjustment_allowed)
                    send_label = (
                        "🚀 SEND ADJUSTED JOBS TO ROUTE OPTIMIZER"
                        if adjustment_allowed
                        else "🚀 SEND SELECTED JOBS TO ROUTE OPTIMIZER"
                    )

                    if st.button(
                        send_label,
                        type="primary",
                        use_container_width=True,
                        disabled=prepare_disabled,
                        key="admin_send_to_route_optimizer",
                    ):
                        invalid = []
                        for _, selected_row in selected_route_rows.iterrows():
                            if not clean_val(selected_row.get("Address")):
                                invalid.append("missing address")
                            if not normalise_postcode(selected_row.get("Postcode")):
                                invalid.append("missing postcode")
                            try:
                                if float(selected_row.get("Price", 0) or 0) <= 0:
                                    invalid.append("price must be above £0")
                            except Exception:
                                invalid.append("invalid price")

                        # Re-read the permanent route immediately before staging the local working
                        # copy. This closes the gap between opening the Admin screen and clicking Send.
                        current_saved_route = load_route_snapshot(target_route_str)
                        current_route_locked = current_saved_route is not None
                        current_adjustment_allowed = bool(
                            current_route_locked
                            and st.session_state.get("admin_adjust_saved_route_date") == target_route_str
                        )

                        current_has_progress = False
                        if current_saved_route is not None:
                            current_jobs = list(current_saved_route.get("jobs_data") or [])
                            current_has_progress = bool(current_saved_route.get("report_b64"))
                            if not current_has_progress:
                                for current_job in current_jobs:
                                    if clean_val(current_job.get("Status")).lower() == "completed":
                                        current_has_progress = True
                                        break

                        progress_override_confirmed = bool(
                            st.session_state.get("admin_adjust_progress_override_date") == target_route_str
                        )

                        if invalid:
                            st.error(
                                "Selected customers cannot be prepared: "
                                + ", ".join(sorted(set(invalid)))
                            )
                        elif current_route_locked and not current_adjustment_allowed:
                            st.error(
                                "That date has a protected saved route. Click ADJUST SAVED ROUTE first. Nothing was changed."
                            )
                        elif current_route_locked and current_has_progress and not progress_override_confirmed:
                            st.error(
                                "This saved route gained completed/report progress after adjustment started. "
                                "Return to Admin → Prepare Route and confirm the progress reset before replacing it. "
                                "The permanent route was not changed."
                            )
                        else:
                            prepared = selected_route_rows.copy().reset_index(drop=True)
                            prepared["Dates"] = target_route_str
                            prepared["service_date"] = target_route_str
                            prepared["Postcode"] = prepared["Postcode"].map(normalise_postcode)
                            prepared["Phone"] = prepared["Phone"].fillna("").astype(str).map(normalise_phone)
                            prepared["Price"] = pd.to_numeric(prepared["Price"], errors="coerce").fillna(0.0)
                            prepared["Cleaning Plan"] = prepared["Cleaning Plan"].fillna("").map(normalise_cleaning_plan)
                            prepared["Notes"] = prepared["Notes"].fillna("").astype(str).str.strip()
                            prepared["Status"] = "pending"
                            prepared["Payment"] = "Waiting"
                            prepared["PaymentTime"] = ""
                            prepared["CompletedTime"] = ""
                            # Match the existing spreadsheet-to-optimiser contract: the next
                            # due date is calculated after completion from the cleaning plan.
                            prepared["Next Cleaning Due"] = ""
                            prepared["route_order"] = None
                            prepared["latitude"] = None
                            prepared["longitude"] = None
                            prepared["geo_query"] = ""
                            prepared["created_at"] = now_text()
                            prepared["address_text"] = prepared["Address"].fillna("").astype(str)
                            prepared["job_id"] = [
                                make_job_id(
                                    target_route_str,
                                    row_number,
                                    row.get("Postcode"),
                                    row.get("Phone"),
                                )
                                for row_number, (_, row) in enumerate(prepared.iterrows(), start=1)
                            ]

                            keep_cols = [
                                "Dates", "Postcode", "Address", "Price", "Phone",
                                "Cleaning Plan", "Notes", "job_id", "service_date",
                                "Status", "Payment", "PaymentTime", "CompletedTime",
                                "Next Cleaning Due", "route_order", "address_text",
                                "latitude", "longitude", "geo_query", "created_at"
                            ]
                            prepared = prepared[keep_cols]

                            # ADMIN adjustment stages only the local working copy. The original
                            # permanent Supabase route is deliberately left untouched here.
                            delete_day(target_route_str)
                            save_dataframe(prepared)
                            st.session_state["master_df"] = prepared.reset_index(drop=True)
                            st.session_state["service_date"] = target_route_str
                            st.session_state.pop("route_data", None)
                            st.session_state.pop("failed_jobs", None)
                            st.session_state.pop("uploaded_filename", None)
                            st.session_state["start_new_day_mode"] = True
                            # Existing save protection already understands this flag. It is set
                            # only after the explicit Admin adjustment confirmation above, so the
                            # normal Driver app and the V26.13 optimiser remain unchanged.
                            st.session_state["replace_saved_route_allowed"] = bool(current_route_locked)
                            # ADMIN replacement only: ensure an old report is not silently attached
                            # to a newly selected/re-optimised route. The normal Driver save path is unchanged.
                            st.session_state["admin_replacement_clear_report"] = bool(current_route_locked)
                            st.session_state.pop("admin_adjust_saved_route_date", None)
                            st.session_state.pop("admin_adjust_confirm_progress_date", None)
                            st.session_state.pop("admin_adjust_progress_override_date", None)
                            st.session_state["admin_office_view"] = False
                            st.rerun()

                st.markdown("---")
                st.caption(
                    "Normal workflow: Admin customers → Route Optimizer → SAVE / LOCK THIS ROUTE FOR PHONE. "
                    "Excel remains available only as a fallback/import tool; it is not required here."
                )

    elif admin_tab == "📊 Daily Reports":
        st.header("📊 Daily Reports")
        report_routes = []
        for snapshot in routes:
            data = snapshot.get("route_data") or {}
            if data.get("report_b64"):
                report_routes.append((snapshot, data))
        if not report_routes:
            st.info("No saved Daily Reports yet. Reports saved by the Driver/Route workflow will appear here automatically.")
        else:
            st.caption(f"{len(report_routes)} saved report(s)")
            for snapshot, data in report_routes:
                route_date = clean_val(snapshot.get("route_date"))
                try:
                    date_label = pd.to_datetime(route_date).strftime("%d/%m/%Y")
                except Exception:
                    date_label = route_date
                jobs_data = data.get("jobs_data", []) or []
                completed = [j for j in jobs_data if clean_val(j.get("Status")).lower() == "completed"]
                revenue = sum(float(j.get("Price", 0) or 0) for j in completed)
                filename = clean_val(data.get("report_filename")) or f"DanCleanUK_Daily_Report_{route_date}.xlsx"
                try:
                    report_bytes = base64.b64decode(data.get("report_b64") or "")
                except Exception:
                    report_bytes = b""
                with st.container(border=True):
                    c1, c2, c3 = st.columns([3, 2, 2])
                    c1.markdown(f"**{date_label}**")
                    c2.markdown(f"{len(completed)} completed job(s)  \n**£{revenue:.2f}**")
                    if report_bytes:
                        c3.download_button("⬇️ Download Excel", data=report_bytes, file_name=filename, mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key=f"admin_report_{route_date}", use_container_width=True)

    else:
        st.header("👥 Customers")
        st.caption("Permanent customer book · automatically grouped into postcode zones")

        if "admin_add_customer_open" not in st.session_state:
            st.session_state["admin_add_customer_open"] = False

        top1, top2 = st.columns([3, 1])
        history_customers = _admin_customer_rows(routes)
        table_ready = _admin_customer_table_ready()
        if table_ready:
            # Route history is only a one-time seed. Once the permanent customer
            # book exists, edits/deletes must remain the source of truth.
            all_customer_records = _admin_load_customer_records(active_only=False)
            if not all_customer_records:
                _admin_sync_history_customers(history_customers)
            manual_customers = _admin_load_customer_records(active_only=True)
        else:
            manual_customers = []
        # Number 2 — Admin Excel backup / customer updates.
        # Supabase remains the source of truth; Excel is a readable backup and
        # a safe way to update existing customer details in bulk.
        if table_ready:
            with st.expander("📦 Customer Data / Excel Backup", expanded=False):
                st.caption(
                    "Download a clean Excel backup of customers, cleaning history and payments. "
                    "You can edit existing customer details in the Customers sheet and upload it here to apply those changes."
                )
                all_for_backup = _admin_load_customer_records(active_only=False)
                backup_bytes = _admin_build_customer_backup_xlsx(all_for_backup, routes)
                backup_name = f"DanCleanUK_Customer_Backup_{datetime.now(ZoneInfo('Europe/London')).strftime('%Y-%m-%d')}.xlsx"
                b1, b2 = st.columns([2, 1])
                b1.download_button(
                    "⬇️ Export Customer Data / Backup",
                    data=backup_bytes,
                    file_name=backup_name,
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    use_container_width=True,
                    key="admin_customer_excel_backup_download",
                )
                if b2.button("🔄 Refresh Customers", use_container_width=True, key="admin_refresh_customer_book"):
                    st.rerun()

                st.markdown("#### Update existing customers from Excel")
                st.caption(
                    "For safety, Address + Postcode identify the customer. Keep those two columns unchanged here. "
                    "Use the normal Edit Customer button if an address/postcode itself needs changing."
                )
                customer_excel = st.file_uploader(
                    "Upload edited DanCleanUK Excel backup",
                    type=["xlsx"],
                    key="admin_customer_excel_update_file",
                )
                if customer_excel is not None:
                    preview = _admin_preview_customer_excel_updates(customer_excel, manual_customers)
                    if preview["errors"]:
                        for error in preview["errors"]:
                            st.error(error)
                    if preview["unmatched"]:
                        st.warning(
                            f"{len(preview['unmatched'])} row(s) were not matched and will be skipped. "
                            "New customers are still added with ➕ Add Customer."
                        )
                        with st.expander("Show unmatched rows"):
                            for item in preview["unmatched"]:
                                st.write(f"• {item}")
                    changes = preview["changes"]
                    if changes:
                        st.success(f"{len(changes)} existing customer(s) have changes ready to apply.")
                        preview_rows = []
                        for change in changes:
                            preview_rows.append({
                                "Customer": f"{change['address']}, {change['postcode']}",
                                "Changes": ", ".join(change["changed_fields"]),
                            })
                        st.dataframe(pd.DataFrame(preview_rows), hide_index=True, use_container_width=True)
                        st.info("Your current Supabase customer book is not changed until you press Apply Excel Updates.")
                        if st.button(
                            f"✅ Apply {len(changes)} Excel Update(s)",
                            type="primary",
                            use_container_width=True,
                            key="admin_apply_customer_excel_updates",
                        ):
                            updated, failed = _admin_apply_customer_excel_updates(changes)
                            if updated:
                                st.success(f"Updated {updated} customer(s).")
                            if failed:
                                for failure in failed:
                                    st.error(failure)
                            if updated and not failed:
                                st.rerun()
                    elif not preview["errors"]:
                        st.info("No customer changes found in this Excel file.")

        top1.metric("Customers", len(manual_customers) if table_ready else len(history_customers))
        if top2.button("➕ Add Customer", type="primary", use_container_width=True, key="admin_add_customer_button"):
            st.session_state["admin_add_customer_open"] = not st.session_state["admin_add_customer_open"]

        if st.session_state["admin_add_customer_open"]:
            with st.container(border=True):
                st.subheader("➕ Add Customer")
                with st.form("admin_add_customer_form", clear_on_submit=False):
                    c1, c2 = st.columns([2, 1])
                    address = c1.text_input("Address *", placeholder="e.g. 10 High Street")
                    postcode = c2.text_input("Postcode *", placeholder="e.g. NG31 9RA")
                    c3, c4, c5 = st.columns(3)
                    phone = c3.text_input("Phone")
                    price = c4.number_input("Normal price (£)", min_value=0.0, step=1.0, value=20.0)
                    cleaning_plan = c5.selectbox("Cleaning Plan", ["", "1 Month", "2 Months", "3 Months", "4 Months", "6 Months", "12 Months"])
                    use_due = st.checkbox("Set Next Cleaning Due now", value=False)
                    next_due_input = st.date_input(
                        "Next Cleaning Due",
                        value=datetime.now(ZoneInfo("Europe/London")).date(),
                        help="The date is only saved when 'Set Next Cleaning Due now' is ticked.",
                    )
                    next_due = next_due_input if use_due else None
                    notes = st.text_area("Notes", height=90)
                    preview_zone = _admin_auto_zone(postcode) if postcode else "—"
                    st.caption(f"Automatic zone: {preview_zone}")
                    submitted = st.form_submit_button("💾 Save Customer", type="primary", use_container_width=True)
                    if submitted:
                        if not clean_val(address) or not normalise_postcode(postcode):
                            st.error("Address and postcode are required.")
                        else:
                            ok, message = _admin_add_customer(address, postcode, phone, price, cleaning_plan, next_due, notes)
                            if ok:
                                st.session_state["admin_add_customer_open"] = False
                                st.rerun()
                            else:
                                st.error(message)

        if table_ready:
            cards = []
            for row in manual_customers:
                cards.append({
                    "Customer ID": row.get("id"),
                    "Address": clean_val(row.get("address")),
                    "Postcode": normalise_postcode(row.get("postcode")),
                    "Phone": clean_val(row.get("phone")),
                    "Price": float(row.get("price", 0) or 0),
                    "Cleaning Plan": normalise_cleaning_plan(row.get("cleaning_plan")),
                    "Next Cleaning Due": clean_val(row.get("next_cleaning_due")),
                    "Planned Service Date": clean_val(row.get("planned_service_date")),
                    "Notes": clean_val(row.get("notes")),
                    "Zone": clean_val(row.get("zone")) or _admin_auto_zone(row.get("postcode")),
                })
        else:
            cards = []
            for row in history_customers:
                item = dict(row)
                item["Customer ID"] = None
                item["Zone"] = _admin_auto_zone(item.get("Postcode"))
                cards.append(item)
            if cards:
                st.info("These customers are from saved route history. Run the supplied one-time Supabase customer setup before using Add Customer.")

        if not cards:
            st.info("No customers yet. Use ➕ Add Customer to create the first one.")
        else:
            zone_names = sorted({clean_val(x.get("Zone")) or "Unzoned" for x in cards})
            selected_zone = st.selectbox("Zone", ["All zones"] + zone_names, key="admin_customer_zone_filter")
            search_customer = st.text_input("Search customers", placeholder="Address, postcode or phone", key="admin_customer_search").strip().casefold()
            visible_cards = []
            for item in cards:
                zone = clean_val(item.get("Zone")) or "Unzoned"
                haystack = " ".join([clean_val(item.get("Address")), normalise_postcode(item.get("Postcode")), clean_val(item.get("Phone"))]).casefold()
                if selected_zone != "All zones" and zone != selected_zone:
                    continue
                if search_customer and search_customer not in haystack:
                    continue
                visible_cards.append(item)

            st.caption(f"Showing {len(visible_cards)} customer(s)")
            for idx, customer in enumerate(sorted(visible_cards, key=lambda x: (clean_val(x.get("Zone")), clean_val(x.get("Address"))))):
                with st.container(border=True):
                    left, middle, right = st.columns([4, 2, 2])
                    address = clean_val(customer.get("Address")) or "Customer"
                    pc = normalise_postcode(customer.get("Postcode"))
                    phone = clean_val(customer.get("Phone")) or "—"
                    price = float(customer.get("Price", 0) or 0)
                    plan = normalise_cleaning_plan(customer.get("Cleaning Plan")) or "No plan"
                    due = clean_val(customer.get("Next Cleaning Due"))
                    try:
                        due = pd.to_datetime(due).strftime("%d/%m/%Y") if due else "—"
                    except Exception:
                        due = due or "—"
                    zone = clean_val(customer.get("Zone")) or _admin_auto_zone(pc)
                    notes = clean_val(customer.get("Notes"))
                    planned_service = clean_val(customer.get("Planned Service Date"))
                    left.markdown(f"**{address}**  \n{pc} · 📞 {phone}")
                    middle.markdown(f"**£{price:.2f}**  \n{plan} · Next: {due}")
                    right.markdown(f"**📍 Zone {zone}**")
                    if planned_service:
                        try:
                            planned_label = pd.to_datetime(planned_service).strftime("%d/%m/%Y")
                        except Exception:
                            planned_label = planned_service
                        st.caption(f"⏩ One-off moved clean: {planned_label} · regular Next Cleaning Due remains {due}")
                    customer_id = customer.get("Customer ID")
                    if customer_id is not None:
                        edit_state_key = "admin_edit_customer_id"
                        delete_key = f"admin_delete_customer_{customer_id}"
                        confirm_key = f"admin_delete_confirm_{customer_id}"
                        action1, action2 = st.columns([1, 1])
                        if action1.button("✏️ Edit Customer", key=f"admin_edit_customer_{customer_id}", use_container_width=True):
                            if st.session_state.get(edit_state_key) == customer_id:
                                st.session_state.pop(edit_state_key, None)
                            else:
                                st.session_state[edit_state_key] = customer_id
                            st.session_state.pop(confirm_key, None)
                            st.rerun()
                        if action2.button("🗑️ Delete", key=delete_key, use_container_width=True):
                            st.session_state[confirm_key] = True
                            st.session_state.pop(edit_state_key, None)
                            st.rerun()

                        if st.session_state.get(confirm_key):
                            st.warning(f"Delete {address}? This removes the customer from the active customer list.")
                            d1, d2 = st.columns([1, 1])
                            if d1.button("Yes, delete", type="primary", key=f"{delete_key}_yes", use_container_width=True):
                                if _admin_delete_customer(customer_id):
                                    st.session_state.pop(confirm_key, None)
                                    st.rerun()
                                else:
                                    st.error("Could not delete this customer. Please try again.")
                            if d2.button("Cancel", key=f"{delete_key}_cancel", use_container_width=True):
                                st.session_state.pop(confirm_key, None)
                                st.rerun()

                        if st.session_state.get(edit_state_key) == customer_id:
                            st.markdown("#### ✏️ Edit Customer")
                            current_due_raw = clean_val(customer.get("Next Cleaning Due"))
                            current_has_due = bool(current_due_raw)
                            current_due_value = _admin_due_date_value(current_due_raw)
                            plan_options = ["", "1 Month", "2 Months", "3 Months", "4 Months", "6 Months", "12 Months"]
                            current_plan = normalise_cleaning_plan(customer.get("Cleaning Plan"))
                            if current_plan and current_plan not in plan_options:
                                plan_options.append(current_plan)
                            plan_index = plan_options.index(current_plan) if current_plan in plan_options else 0

                            with st.form(f"admin_edit_customer_form_{customer_id}", clear_on_submit=False):
                                e1, e2 = st.columns([2, 1])
                                edit_address = e1.text_input("Address *", value=address)
                                edit_postcode = e2.text_input("Postcode *", value=pc)
                                e3, e4, e5 = st.columns(3)
                                edit_phone = e3.text_input("Phone", value=clean_val(customer.get("Phone")))
                                edit_price = e4.number_input(
                                    "Normal price (£)",
                                    min_value=0.0,
                                    step=1.0,
                                    value=float(price),
                                )
                                edit_plan = e5.selectbox(
                                    "Cleaning Plan",
                                    plan_options,
                                    index=plan_index,
                                )
                                edit_has_due = st.checkbox(
                                    "Keep / set Next Cleaning Due",
                                    value=current_has_due,
                                )
                                edit_due_input = st.date_input(
                                    "Next Cleaning Due",
                                    value=current_due_value,
                                    help="Untick 'Keep / set Next Cleaning Due' to clear this date.",
                                )
                                edit_notes = st.text_area("Notes", value=notes, height=90)
                                st.caption(f"Automatic zone after save: {_admin_auto_zone(edit_postcode) if edit_postcode else '—'}")
                                save_edit = st.form_submit_button("💾 Save Changes", type="primary", use_container_width=True)
                                if save_edit:
                                    if not clean_val(edit_address) or not normalise_postcode(edit_postcode):
                                        st.error("Address and postcode are required.")
                                    else:
                                        edit_due = edit_due_input if edit_has_due else None
                                        ok, message = _admin_update_customer(
                                            customer_id,
                                            edit_address,
                                            edit_postcode,
                                            edit_phone,
                                            edit_price,
                                            edit_plan,
                                            edit_due,
                                            edit_notes,
                                        )
                                        if ok:
                                            st.session_state.pop(edit_state_key, None)
                                            st.rerun()
                                        else:
                                            st.error(message)
                    if notes:
                        st.caption(f"Notes: {notes}")

    # Critical separation: nothing from the locked Driver/Route front renders below.
    st.stop()

